: await (async () => {
    const controller = new AbortController();
    const cancel = () => controller.abort();
    // Only scoped requests own this computation; shared wide reads are independent.
    req.once("aborted", cancel);
    res.once("close", cancel);
    if (req.aborted || res.destroyed) cancel();
    try {
      return await authorizedIssuePage({
        limit, offset, afterId: listFilters.afterId,
        signal: controller.signal,
        keyset: listFilters.sortField === "id" && listFilters.sortDir === "asc",
        read: (cursor) => svc.list(companyId, { ...listFilters, ...cursor }),
        authorize: (rows) => filterIssuesForActor(req, rows),
      });
    } finally {
      req.off("aborted", cancel);
      res.off("close", cancel);
    }
  })();
